CREATE TABLE "bunnproeverlinjer" (
  "objid" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "objtype" text NOT NULL DEFAULT 'BunnprøverLinjer',
  "identifikasjon_lokalid" text NOT NULL,
  "identifikasjon_navnerom" text NOT NULL,
  "identifikasjon_versjonid" text NOT NULL,
  "kvalitet_maalemetode" text,
  "datauttaksdato" timestamp with time zone,
  "opphav" text NOT NULL,
  "linje" geometry(LineString, 25833) NOT NULL,
  "redskap" text NOT NULL,
  "toktnummer" integer NOT NULL,
  "referansestasjon" integer NOT NULL,
  "stasjonnummer" integer NOT NULL,
  "proevenummer" integer NOT NULL,
  "redskapkode" integer NOT NULL,
  "dato" date NOT NULL,
  "lengdegrad" double precision NOT NULL,
  "breddegrad" double precision NOT NULL,
  "bunndyp" integer NOT NULL
);

ALTER TABLE "bunnproeverlinjer" ADD CONSTRAINT "bunnproeverlinjer_kvalitet_maalemetode_fkey" FOREIGN KEY ("kvalitet_maalemetode") REFERENCES "maalemetode" ("identifier") ON DELETE NO ACTION;

CREATE INDEX "bunnproeverlinjer_linje_gist" ON "bunnproeverlinjer" USING GIST ("linje");
CREATE INDEX "bunnproeverlinjer_kvalitet_maalemetode_idx" ON "bunnproeverlinjer" ("kvalitet_maalemetode");

