@ps {"from":"GenerelleEgenskaperStasjoner","path":[{"name":"datauttaksdato","type":"DateTime","cardinality":"0..1","taggedValues":{"SOSI_navn":"DATAUTTAKSDATO"},"@i":2}]}';
COMMENT ON COLUMN "bunnproeverlinjer"."opphav" IS 'referanse til opphavsmaterialet, kildematerialet, organisasjons/publiseringskilde
