@ps {"from":"BunnprøverLinjer","path":[{"name":"redskap","type":"CharacterString","cardinality":"1","taggedValues":{"SOSI_navn":"REDSKAP"},"@i":1}]}';
COMMENT ON COLUMN "bunnproeverlinjer"."toktnummer" IS 'toktnummer ved Havforskningsinstituttet.
