@ps {"from":"BunnprøverLinjer","path":[{"name":"toktNummer","type":"Integer","cardinality":"1","taggedValues":{"SOSI_navn":"TOKTNUMMER"},"@i":2}]}';
COMMENT ON COLUMN "bunnproeverlinjer"."referansestasjon" IS 'referansestasjon, unik innen MAREANO.
