Reference number during MAREANO prosject (superstation).

@ps {"from":"BunnprøverLinjer","path":[{"name":"referanseStasjon","type":"Integer","cardinality":"1","taggedValues":{"SOSI_navn":"REFERANSESTASJON"},"@i":3}]}';
COMMENT ON COLUMN "bunnproeverlinjer"."stasjonnummer" IS '@ps {"from":"BunnprøverLinjer","path":[{"name":"stasjonNummer","type":"Integer","cardinality":"1","taggedValues":{"SOSI_navn":"STASJONNUMMER"},"@i":4}]}';
COMMENT ON COLUMN "bunnproeverlinjer"."proevenummer" IS '@ps {"from":"BunnprøverLinjer","path":[{"name":"prøveNummer","type":"Integer","cardinality":"1","taggedValues":{"SOSI_navn":"PRØVENUMMER"},"@i":5}]}';
COMMENT ON COLUMN "bunnproeverlinjer"."redskapkode" IS '@ps {"from":"BunnprøverLinjer","path":[{"name":"redskapKode","type":"Integer","cardinality":"1","taggedValues":{"SOSI_navn":"REDSKAPKODE"},"@i":6}]}';
COMMENT ON COLUMN "bunnproeverlinjer"."dato" IS 'observasjonsdato.
