@ps {"from":"BunnprøverLinjer","path":[{"name":"breddegrad","type":"Real","cardinality":"1","taggedValues":{"SOSI_navn":"BREDDEGRAD"},"@i":9}]}';
COMMENT ON COLUMN "bunnproeverlinjer"."bunndyp" IS 'bunndyp der prøven er tatt.
